using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.Logging;using RandomNumbersApi.Models;using RandomNumbersApi.Services;namespace RandomNumbersApi.Controllers{[ApiController][Route("api/[controller]")]public class ItemsController : ControllerBase{private readonly ILogger<ItemsController> _logger;private readonly IItemService _service;public ItemsController(ILogger<ItemsController> logger, IItemService service){_logger = logger;_service = service;}[HttpGet]public async Task<ActionResult<IEnumerable<Item>>> GetAllAsync(CancellationToken cancellationToken){var items = await _service.GetAllAsync(cancellationToken);return Ok(items);} [HttpGet("{id:int}")]public async Task<ActionResult<Item>> GetByIdAsync(int id, CancellationToken cancellationToken){var item = await _service.GetByIdAsync(id, cancellationToken);if(item == null){return NotFound(new ProblemDetails{Title = "Item not found",Detail = $"No item with id {id} exists.",Status = StatusCodes.Status404NotFound});}return Ok(item);} [HttpPost]public async Task<ActionResult<Item>> CreateAsync([FromBody] Item item, CancellationToken cancellationToken){if(!ModelState.IsValid){return ValidationProblem(ModelState);}item.Id = 0;item.CreatedAt = DateTime.UtcNow;var created = await _service.CreateAsync(item, cancellationToken);return CreatedAtAction(nameof(GetByIdAsync), new { id = created.Id }, created);} [HttpPut("{id:int}")]public async Task<IActionResult> UpdateAsync(int id, [FromBody] Item item, CancellationToken cancellationToken){if(id <= 0){return BadRequest(new ProblemDetails{Title = "Invalid id",Detail = "The provided id must be greater than zero.",Status = StatusCodes.Status400BadRequest});}if(!ModelState.IsValid){return ValidationProblem(ModelState);}var updated = await _service.UpdateAsync(id, item, cancellationToken);if(!updated){return NotFound(new ProblemDetails{Title = "Item not found",Detail = $"No item with id {id} exists.",Status = StatusCodes.Status404NotFound});}return NoContent();} [HttpDelete("{id:int}")]public async Task<IActionResult> DeleteAsync(int id, CancellationToken cancellationToken){if(id <= 0){return BadRequest(new ProblemDetails{Title = "Invalid id",Detail = "The provided id must be greater than zero.",Status = StatusCodes.Status400BadRequest});}var deleted = await _service.DeleteAsync(id, cancellationToken);if(!deleted){return NotFound(new ProblemDetails{Title = "Item not found",Detail = $"No item with id {id} exists.",Status = StatusCodes.Status404NotFound});}return NoContent();}}}